package lazers
import("context";"io";"net/http";"strings";"sync";"testing";"time")
type fakeTransport struct{mu sync.Mutex; statuses []int; bodies []string; err error}
func(f *fakeTransport)Do(r *http.Request)(*http.Response,error){f.mu.Lock();defer f.mu.Unlock();b,_:=io.ReadAll(r.Body);f.bodies=append(f.bodies,string(b));if f.err!=nil{return nil,f.err};s:=202;if len(f.statuses)>0{s=f.statuses[0];f.statuses=f.statuses[1:]};return &http.Response{StatusCode:s,Body:io.NopCloser(strings.NewReader(""))},nil}
func client(t *testing.T,tr *fakeTransport)(*Client){t.Helper();c,e:=NewClient(Config{APIKey:"key",Endpoint:"https://api.test",ProjectID:"project",Environment:"production",ServiceName:"api",HTTPClient:tr,RetryBaseDelay:time.Millisecond});if e!=nil{t.Fatal(e)};return c}
func TestProtocolAndHelpers(t *testing.T){tr:=&fakeTransport{};c:=client(t,tr);defer c.Close(context.Background());c.CaptureError(errorsNew("timeout"),CaptureContext{});if e:=c.Flush(context.Background());e!=nil{t.Fatal(e)};if !strings.Contains(tr.bodies[0],`"protocolVersion":"1"`)||!strings.Contains(tr.bodies[0],`"eventCategory":"error"`){t.Fatal(tr.bodies)};c.CaptureJobFailure("daily",errorsNew("bad"),CaptureContext{});c.Flush(context.Background());if !strings.Contains(tr.bodies[1],"job_failure"){t.Fatal(tr.bodies[1])}}
func TestRedactionIdentityAndFixtures(t *testing.T){tr:=&fakeTransport{};c:=client(t,tr);defer c.Close(context.Background());c.CaptureMessage("hello",CaptureContext{Metadata:map[string]any{"password":"x","nested":map[string]any{"accessToken":"y"}}});c.Flush(context.Background());if !strings.Contains(tr.bodies[0],"[REDACTED]"){t.Fatal(tr.bodies[0])};c.CaptureError(errorsNew("same"),CaptureContext{});c.Flush(context.Background());a:=tr.bodies[1];c.CaptureError(errorsNew("same"),CaptureContext{});c.Flush(context.Background());if fingerprintFrom(a)==""||fingerprintFrom(a)!=fingerprintFrom(tr.bodies[2]){t.Fatal("fingerprint")}}
func TestQueueRetryAndContext(t *testing.T){tr:=&fakeTransport{statuses:[]int{500}};c:=client(t,tr);defer c.Close(context.Background());c.CaptureMessage("x",CaptureContext{});time.Sleep(time.Millisecond);if c.QueueSize()==0{t.Fatal("retryable was dropped")};ctx,cancel:=context.WithTimeout(context.Background(),time.Nanosecond);defer cancel();if c.Flush(ctx)==nil{t.Fatal("expected cancellation")};d,e:=NewClient(Config{APIKey:"k",Endpoint:"x",ProjectID:"p",Environment:"e",ServiceName:"s",Disabled:true,HTTPClient:tr});if e!=nil{t.Fatal(e)};d.CaptureMessage("no",CaptureContext{});if d.QueueSize()!=0{t.Fatal("disabled")}}
func errorsNew(s string)error{return simpleError(s)};type simpleError string;func(e simpleError)Error()string{return string(e)}
func fingerprintFrom(s string)string{i:=strings.Index(s,`"fingerprint":"`);if i<0{return ""};s=s[i+15:];return s[:strings.Index(s,`"`)]}